import math
from fractions import Fraction

def root(n):
    # the square root of a whole number n, in simplest exact form
    k = math.isqrt(n)
    while n % (k * k) != 0:
        k = k - 1
    if k * k == n:
        return f"{k}"
    if k == 1:
        return f"√{n}"
    return f"{k}√{n // (k * k)}"

def pi_str(c):
    # a multiple of pi, written the way you'd write it by hand
    if c == 1:
        return "π"
    if c.denominator == 1:
        return f"{c}π"
    return f"({c})π"

def solve(kind, nums):
    if kind == "angle":
        x = nums[0]
        if x < 90:
            complement = f"{90 - x}"
        else:
            complement = "none"
        print(f"  complement 90 - {x}: {complement}, supplement 180 - {x}: {180 - x}")
    elif kind == "third":
        a, b = nums[0], nums[1]
        c = 180 - a - b
        print(f"  180 - {a} - {b} = {c}")
        if c <= 0:
            print("  not above 0: no triangle")
        elif a == 90 or b == 90 or c == 90:
            print("  a right angle: a right triangle")
        elif a > 90 or b > 90 or c > 90:
            print("  an angle over 90: an obtuse triangle")
        else:
            print("  all under 90: an acute triangle")
    elif kind == "hyp":
        a, b = nums[0], nums[1]
        print(f"  c² = {a}² + {b}² = {a * a + b * b}, so c = {root(a * a + b * b)}")
    elif kind == "polygon":
        n = nums[0]
        total = (n - 2) * 180
        print(f"  sum ({n} - 2) × 180 = {total}, each {Fraction(total, n)}, exterior {Fraction(360, n)}")
    elif kind == "arc":
        r, theta = nums[0], nums[1]
        part = Fraction(theta, 360)
        print(f"  {theta}/360 = {part} of the circle")
        print(f"  arc {part} × 2π({r}) = {pi_str(part * 2 * r)}, sector {part} × π({r})² = {pi_str(part * r * r)}")
    elif kind == "rotate":
        q, x, y = nums[0], nums[1], nums[2]
        print(f"  turn by {90 * q} degrees: {q} % 4 = {q % 4}, the quarter turns left, from ({x}, {y})")
        for i in range(q % 4):
            x, y = -y, x
            print(f"  (x, y) -> (-y, x): ({x}, {y})")

problems = [
    ("Example 1 · 58 degrees", "angle", [58]),
    ("Example 3 · angles 47 and 68", "third", [47, 68]),
    ("Example 4, the other way: legs 7 and 24", "hyp", [7, 24]),
    ("Example 5 · a regular octagon", "polygon", [8]),
    ("Example 7 · radius 12, 45 degrees", "arc", [12, 45]),
    ("Example 10 · (3, -2) by 90 degrees", "rotate", [1, 3, -2]),
    ("No complement: 120 degrees", "angle", [120]),
    ("A right triangle: angles 90 and 36", "third", [90, 36]),
    ("An obtuse triangle: angles 30 and 45", "third", [30, 45]),
    ("No triangle: angles 100 and 85", "third", [100, 85]),
    ("A radical: legs 2 and 4", "hyp", [2, 4]),
    ("A half turn: (-3, 5) by 180 degrees", "rotate", [2, -3, 5]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

