import math
from fractions import Fraction

def root(q):
    # √q for a Fraction q >= 0, simplified: √18 = 3√2, √(13/4) = √13/2
    n = q.numerator * q.denominator
    f = 1
    for d in range(2, math.isqrt(n) + 1):
        if n % (d * d) == 0:
            f = d
    c, rest = Fraction(f, q.denominator), n // (f * f)
    if rest == 1:
        return f"{c}"
    top = f"√{rest}"
    if c.numerator != 1:
        top = f"{c.numerator}√{rest}"
    if c.denominator == 1:
        return top
    return f"{top}/{c.denominator}"

def pi_str(c):
    # a multiple of pi, written the way you'd write it by hand
    if c == 1:
        return "π"
    if c.denominator == 1:
        return f"{c}π"
    return f"({c})π"

def solve(kind, nums):
    if kind == "equal" or kind == "supp":
        p, q, r, s = nums[0], nums[1], nums[2], nums[3]
        if kind == "equal":
            x = Fraction(s - q, p - r)
            print(f"  equal angles: {p}x + ({q}) = {r}x + ({s}), so x = {x}")
        else:
            x = Fraction(180 - q - s, p + r)
            print(f"  supplementary: {p}x + ({q}) + {r}x + ({s}) = 180, so x = {x}")
        print(f"  the angles are {p * x + q} and {r * x + s}")
    elif kind == "circle":
        h, k, F = Fraction(-nums[0], 2), Fraction(-nums[1], 2), nums[2]
        r2 = h * h + k * k - F
        print(f"  complete both squares: h = -D/2 = {h}, k = -E/2 = {k}, right side h² + k² - F = {r2}")
        if r2 > 0:
            print(f"  center ({h}, {k}), radius {root(r2)}")
        elif r2 == 0:
            print(f"  0 on the right: the single point ({h}, {k})")
        else:
            print("  negative on the right: no points")
    elif kind == "heron":
        a, b, c = nums[0], nums[1], nums[2]
        s = Fraction(a + b + c, 2)
        q = s * (s - a) * (s - b) * (s - c)
        print(f"  s = {s}, s(s - a)(s - b)(s - c) = {q}")
        if q > 0:
            print(f"  area √({q}) = {root(q)}")
        elif q == 0:
            print("  zero: a flat triangle")
        else:
            print("  negative: no triangle")
    elif kind == "cone":
        r, h = nums[0], nums[1]
        print(f"  V = (1/3)π({r}²)({h}) = {pi_str(Fraction(r * r * h, 3))}")
        print(f"  slant √({r}² + {h}²) = {root(Fraction(r * r + h * h))}")

problems = [
    ("Example 1 · (3x + 15) and (5x - 25), corresponding", "equal", [3, 15, 5, -25]),
    ("Example 2 · (2x + 10) and (3x - 5), same-side interior", "supp", [2, 10, 3, -5]),
    ("Example 6 · x² + y² - 4x + 6y - 12 = 0", "circle", [-4, 6, -12]),
    ("Example 8 · sides 5, 6, 7", "heron", [5, 6, 7]),
    ("Example 10 · radius 6, height 8", "cone", [6, 8]),
    ("A fraction in the center: x² + y² + 2x - 3y = 0", "circle", [2, -3, 0]),
    ("A single point: x² + y² - 4x + 2y + 5 = 0", "circle", [-4, 2, 5]),
    ("A fraction area: sides 4, 5, 6", "heron", [4, 5, 6]),
    ("No triangle: sides 2, 3, 7", "heron", [2, 3, 7]),
    ("A radical slant: radius 1, height 1", "cone", [1, 1]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

