        L, foot = nums[0], nums[1]
        print(f"  h² = {L}² - {foot}² = {L * L - foot * foot}, so h = {root(L * L - foot * foot)}")
    elif kind == "shadow":
        h, s, S = nums[0], nums[1], nums[2]
        print(f"  H/{S} = {h}/{s}, similar triangles, so H = {S} × {h} / {s} = {Fraction(S * h, s)}")
    elif kind == "field":
        xs, ys, total = [], [], 0
        for k in range(0, len(nums), 2):
            xs.append(nums[k])
            ys.append(nums[k + 1])
        for i in range(len(xs)):
            j = (i + 1) % len(xs)
            total = total + xs[i] * ys[j] - xs[j] * ys[i]
        print(f"  the crisscross products add to {total}, so A = |{total}| / 2 = {Fraction(abs(total), 2)}")
    elif kind == "sector":
        r, theta = nums[0], nums[1]
        part = Fraction(theta, 360)
