from fractions import Fraction

def solve(kind, nums):
    if kind == "classify":
        a, b, c = nums[0], nums[1], nums[2]
        if a > b:
            a, b = b, a
        if b > c:
            b, c = c, b
        if a > b:
            a, b = b, a
        print(f"  sorted {a}, {b}, {c}: {a} + {b} = {a + b}, a² + b² = {a * a + b * b}, c² = {c * c}")
        if a + b <= c:
            print("  the two short sides don't reach: not a triangle")
        elif c * c == a * a + b * b:
            print("  equal: a right triangle")
        elif c * c < a * a + b * b:
            print("  c² is smaller: acute")
        else:
            print("  c² is larger: obtuse")
    elif kind == "regular":
        angle = nums[0]
        e = 180 - angle
        if 360 % e == 0:
            print(f"  exterior {e}, and 360 / {e} = {360 // e} sides")
        else:
            print(f"  exterior {e}, and 360 / {e} = {Fraction(360, e)} isn't whole: no such polygon")
    elif kind == "conic":
        A, C, D, E, F = nums[0], nums[1], nums[2], nums[3], nums[4]
        if A == 0 or C == 0:
            print("  only one square: a parabola")
            return
        h, k = Fraction(-D, 2 * A), Fraction(-E, 2 * C)
        G = A * h * h + C * k * k - F
        print(f"  complete both squares: h = -D/(2A) = {h}, k = -E/(2C) = {k}, G = Ah² + Ck² - F = {G}")
        if A * C < 0:
            if G == 0:
                print(f"  opposite signs and 0 on the right: two lines through ({h}, {k})")
            else:
                print(f"  opposite signs: a hyperbola, center ({h}, {k})")
        elif G * A < 0:
            print("  the same signs, but the right side has the other sign: no points")
        elif G == 0:
            print(f"  the same signs and 0 on the right: the point ({h}, {k})")
        elif A == C:
            print(f"  the same signs and A = C: a circle, center ({h}, {k})")
        else:
            print(f"  the same signs and A ≠ C: an ellipse, center ({h}, {k})")
    elif kind == "turn":
        q, a, b, x, y = nums[0], nums[1], nums[2], nums[3], nums[4]
        u, v = x - a, y - b
        print(f"  slide ({a}, {b}) to the origin: ({u}, {v})")
        for i in range(q % 4):
            u, v = -v, u
        print(f"  {q} % 4 = {q % 4}, so turn {q % 4} × 90 degrees: ({u}, {v}), slide back: ({u + a}, {v + b})")

