from fractions import Fraction

def solve(kind, nums):
    if kind == "classify":
        a, b, c = nums[0], nums[1], nums[2]
        if a > b:
            a, b = b, a
        if b > c:
            b, c = c, b
        if a > b:
            a, b = b, a
        if a + b <= c:
            name = "not a triangle"
        elif c * c == a * a + b * b:
            name = "right"
        elif c * c < a * a + b * b:
            name = "acute"
        else:
            name = "obtuse"
        return f"classify: {a}, {b}, {c}: {name}"
    if kind == "regular":
        e = 180 - nums[0]
        if 360 % e == 0:
            return f"regular: angle {nums[0]}: n = {360 // e}"
        return f"regular: angle {nums[0]}: none"
    if kind == "conic":
        A, C, D, E, F = nums[0], nums[1], nums[2], nums[3], nums[4]
        if A == 0 or C == 0:
            return "conic: parabola"
        h, k = Fraction(-D, 2 * A), Fraction(-E, 2 * C)
        G = A * h * h + C * k * k - F
        if A * C < 0:
            if G == 0:
                return "conic: two lines"
            return "conic: hyperbola"
        if G * A < 0:
            return "conic: no points"
        if G == 0:
            return "conic: point"
        if A == C:
            return "conic: circle"
        return "conic: ellipse"
    q, a, b, x, y = nums[0], nums[1], nums[2], nums[3], nums[4]
    u, v = x - a, y - b
    for i in range(q % 4):
        u, v = -v, u
    return f"turn: ({x}, {y}) -> ({u + a}, {v + b})"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))
